import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices } from '../src/reports.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices: returns empty array when no invoices', () => {
  const result = overdueInvoices([], '2026-12-31');
  assert.deepEqual(result, []);
});

test('overdueInvoices: returns empty array when no overdue invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
    terms: 'NET30',
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  // Invoice due date is 2026-11-06, check as of 2026-11-05
  const result = overdueInvoices([issued.value], '2026-11-05');
  assert.deepEqual(result, []);
});

test('overdueInvoices: includes invoice that is one day overdue', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
    terms: 'NET30',
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  // Invoice due date is 2026-11-06, check as of 2026-11-07
  const result = overdueInvoices([issued.value], '2026-11-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.value.number);
  assert.equal(result[0].daysOverdue, 1);
});

test('overdueInvoices: excludes draft invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
    terms: 'NET30',
  });
  assert.ok(invResult.ok);

  const result = overdueInvoices([invResult.value], '2026-12-31');
  assert.deepEqual(result, []);
});

test('overdueInvoices: excludes paid invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
    terms: 'NET30',
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const paymentResult = recordPayment(issued.value, { amount: 91960, date: '2026-11-07' });
  assert.ok(paymentResult.ok);

  const result = overdueInvoices([paymentResult.value], '2026-12-31');
  assert.deepEqual(result, []);
});

test('overdueInvoices: includes partially paid invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
    terms: 'NET30',
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const paymentResult = recordPayment(issued.value, { amount: 30000, date: '2026-11-07' });
  assert.ok(paymentResult.ok);

  const result = overdueInvoices([paymentResult.value], '2026-11-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, 61960);
});

test('overdueInvoices: sorts by daysOverdue descending', () => {
  // Create three invoices with different due dates
  const inv1Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.ok(inv1Result.ok);
  const issued1 = issueInvoice(inv1Result.value, []);
  assert.ok(issued1.ok);

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-02-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.ok(inv2Result.ok);
  const issued2 = issueInvoice(inv2Result.value, [issued1.value.number]);
  assert.ok(issued2.ok);

  const inv3Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-03-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.ok(inv3Result.ok);
  const issued3 = issueInvoice(inv3Result.value, [issued1.value.number, issued2.value.number]);
  assert.ok(issued3.ok);

  // Check as of 2026-04-01: inv1 due 2026-01-15, inv2 due 2026-02-15, inv3 due 2026-03-15
  const result = overdueInvoices([issued3.value, issued1.value, issued2.value], '2026-04-01');
  assert.equal(result.length, 3);
  assert.equal(result[0].number, issued1.value.number);
  assert.ok(result[0].daysOverdue > result[1].daysOverdue);
  assert.equal(result[1].number, issued2.value.number);
  assert.ok(result[1].daysOverdue > result[2].daysOverdue);
  assert.equal(result[2].number, issued3.value.number);
});

test('overdueInvoices: calculates daysOverdue correctly', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  // Due date: 2026-01-15, check as of 2026-01-25
  const result = overdueInvoices([issued.value], '2026-01-25');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 10);
});

test('overdueInvoices: includes correct fields', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
    terms: 'NET30',
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const result = overdueInvoices([issued.value], '2026-12-31');
  assert.equal(result.length, 1);
  const inv = result[0];

  assert.ok('number' in inv);
  assert.ok('customerId' in inv);
  assert.ok('dueDate' in inv);
  assert.ok('daysOverdue' in inv);
  assert.ok('due' in inv);
  assert.equal(inv.number, issued.value.number);
  assert.equal(inv.customerId, 'C-002');
  assert.equal(inv.dueDate, '2026-11-06');
});

test('overdueInvoices: calculates due correctly', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const result = overdueInvoices([issued.value], '2026-12-31');
  assert.equal(result.length, 1);
  // Total for unpaid invoice is 91960
  assert.equal(result[0].due, 91960);
});

test('overdueInvoices: calculates due correctly for partially paid', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
