test('overdueInvoices: sorts by daysOverdue descending', () => {
  // Create three invoices with different due dates
  const inv1Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.ok(inv1Result.ok);
  const issued1 = issueInvoice(inv1Result.value, []);
  assert.ok(issued1.ok);

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-02-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.ok(inv2Result.ok);
  const issued2 = issueInvoice(inv2Result.value, [issued1.value.number]);
  assert.ok(issued2.ok);

  const inv3Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-03-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.ok(inv3Result.ok);
  const issued3 = issueInvoice(inv3Result.value, [issued1.value.number, issued2.value.number]);
  assert.ok(issued3.ok);

  // Check as of 2026-04-01: inv1 due 2026-01-15, inv2 due 2026-02-15, inv3 due 2026-03-15
  const result = overdueInvoices([issued3.value, issued1.value, issued2.value], '2026-04-01');
  assert.equal(result.length, 3);
  assert.equal(result[0].number, issued1.value.number);
  assert.ok(result[0].daysOverdue > result[1].daysOverdue);
  assert.equal(result[1].number, issued2.value.number);
  assert.ok(result[1].daysOverdue > result[2].daysOverdue);
  assert.equal(result[2].number, issued3.value.number);
});

