test('overdueInvoices: many days overdue', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  // Due 2026-01-15, check 2027-01-15 (one year later)
  const result = overdueInvoices([issued.value], '2027-01-15');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 365);
});

test('overdueInvoices: with discount and VAT', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 8, discountPercent: 10 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const result = overdueInvoices([issued.value], '2026-12-31');
  assert.equal(result.length, 1);
  // Total with 10% discount: 76000 - 7600 + 14364 = 82764
  assert.equal(result[0].due, 82764);
});

test('overdueInvoices: same due date invoices maintain relative order', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.ok(inv1Result.ok);
  const issued1 = issueInvoice(inv1Result.value, []);
  assert.ok(issued1.ok);

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.ok(inv2Result.ok);
  const issued2 = issueInvoice(inv2Result.value, [issued1.value.number]);
  assert.ok(issued2.ok);

  const result = overdueInvoices([issued1.value, issued2.value], '2026-02-01');
  assert.equal(result.length, 2);
  assert.equal(result[0].daysOverdue, result[1].daysOverdue);
  // Both should be included when both have same due date
});

