test('vatSummary: single line with 21% VAT', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const result = vatSummary([issued.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // Line total: 76000, no discount, base: 76000, VAT: 15960
  assert.equal(result[0].base, 76000);
  assert.equal(result[0].vat, 15960);
});

