test('vatSummary: correct fields in output', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const result = vatSummary([issued.value]);
  assert.equal(result.length, 1);
  const entry = result[0];

  assert.ok('rate' in entry);
  assert.ok('base' in entry);
  assert.ok('vat' in entry);
  assert.strictEqual(Object.keys(entry).length, 3);
});

test('vatSummary: multiple customers', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(inv1Result.ok);
  const issued1 = issueInvoice(inv1Result.value, []);
  assert.ok(issued1.ok);

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(inv2Result.ok);
  const issued2 = issueInvoice(inv2Result.value, [issued1.value.number]);
  assert.ok(issued2.ok);

  const result = vatSummary([issued1.value, issued2.value]);
  // VAT is aggregated across all customers
  assert.equal(result.length, 1);
  assert.equal(result[0].vat, 31920);
});
